#[derive(Debug)] pub struct IntegrationHarness { identity:PlatformIntegrationIdentity,bundle:CrossCertificateBundle,scenario:IntegrationScenarioFixture,state:IntegrationRunState,receipts:Vec<IntegrationStepReceipt>,audit:AssuranceAuditChain }
impl IntegrationHarness { pub fn new(identity:PlatformIntegrationIdentity,bundle:CrossCertificateBundle,scenario:IntegrationScenarioFixture,audit_genesis:impl Into<String>)->Result<Self,AssuranceError>{identity.verify()?;bundle.verify()?;scenario.verify()?;if identity.policy_snapshot_sha256!=bundle.policy_snapshot_sha256||identity.policy_snapshot_sha256!=scenario.policy_snapshot_sha256{return Err(AssuranceError::InvalidBinding("integration policy mismatch".into()));} Ok(Self{identity,bundle,scenario,state:IntegrationRunState::Created,receipts:Vec::new(),audit:AssuranceAuditChain::new(audit_genesis)?})} pub fn start(&mut self)->Result<(),AssuranceError>{if self.state!=IntegrationRunState::Created{return Err(AssuranceError::InvalidTransition("integration start".into()));} self.state=IntegrationRunState::Running;self.audit.append(AssuranceAuditEvent{action:"integration_started".into(),subject_id:self.identity.integration_id.clone(),outcome:"running".into(),metadata:BTreeMap::from([("scenario_sha256".into(),self.scenario.scenario_sha256.clone())])})?;Ok(())}}
